const h1 = code.match(/<h1\s*>[\s\S]*?<\/h1\s*>/gi) ?? [];
if (h1.length !== 1) {
  throw new Error(`Expected exactly one <h1>, found ${h1.length}.`);
}

const m = code.match(/<h1\s*>([\s\S]*?)<\/h1\s*>/i);
if (!m || m[1].trim().length === 0) {
  throw new Error("The <h1> is empty — put your name between the tags.");
}

const p = code.match(/<p\s*>([\s\S]*?)<\/p\s*>/i);
if (!p || !/^I am learning/i.test(p[1].trim())) {
  throw new Error("Add a <p> that starts with the words 'I am learning'.");
}
